const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
let local=read('abismo-local-v1',{id:crypto.randomUUID(),name:'Viajante',meta:emptyMeta(),room:null});local.meta=normalizeMeta(local.meta);
let profile=local,room=local.room,mode='local',client,channel,timer,serverList=[],busy=false,panel=room?null:'create',target=null,pending=null,inspect=null,selected=new Set(),talentSeen='',selectedClass='guerreiro',selectedRace='humano',draftSpecial=Object.fromEntries(SPECIAL.map(x=>[x.id,5])),draftTraits=[],draftName=local.name,runes=['IGNIS','IGNIS'];
let echoOpen='survival';let traitFilter='all',traitsExpanded=false;let draftServer='Expedição',draftJoin='',treeBranch=0,logOpen=false,fxLock=false,restorePanel=null;
const uiStats=new WeakMap();function stats(p){if(!uiStats.has(p))uiStats.set(p,calculateStats(p));return uiStats.get(p);}
let director,effects,tooltips,frame=0,arenaHold=null,holdTimer=0,queuedFX=[],deltaBefore=null,lastReceiveAt=0,realtimeStatus='CLOSED',saveTimer=0;
