const fxCursor=new FXCursor();fxCursor.seed(room);
function scheduleRender(){if(frame)return;frame=requestAnimationFrame(()=>{frame=0;render();flushFX();})}
function queueSave(){clearTimeout(saveTimer);saveTimer=setTimeout(save,100)}
addEventListener('pagehide',()=>{clearTimeout(saveTimer);save()});
const config=window.ABISMO_CONFIG||{},player=()=>room?.state.players.find(p=>p.id===profile.id),meta=()=>player()?.meta||profile.meta;
const btn=(label,op,data='',disabled=false,cls='')=>`<button data-do="${op}" ${data} class="${cls}" ${disabled?'disabled':''}>${label}</button>`;
const meter=(n,max,kind='hp')=>`<span class="meter ${kind}"><i style="width:${Math.max(0,Math.min(100,n/(max||1)*100))}%"></i></span>`;
function save(){if(mode==='local'){local=profile;local.room=room;localStorage.setItem('abismo-local-v1',JSON.stringify(local));}}
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
let audioContext;let soundOn=read('abismo-sound',true);
function sound(kind='click') {if(!soundOn)return;try{audioContext??=new AudioContext();audioContext.resume();const notes=kind==='vote'?[659,880,659,880]:kind==='voteEnd'?[880,1047]:kind==='heal'?[392,523,659]:kind==='spell'?[180,360,720]:kind==='attack'?[170,70]:kind==='hurt'?[95,55]:kind==='level'?[392,494,587,784]:[440];for(const [i,f] of notes.entries()){const osc=audioContext.createOscillator(),gain=audioContext.createGain(),at=audioContext.currentTime+i*.07;osc.type=kind==='attack'?'sawtooth':'triangle';osc.frequency.setValueAtTime(f,at);osc.frequency.exponentialRampToValueAtTime(Math.max(30,f*.65),at+.12);gain.gain.setValueAtTime(.045,at);gain.gain.exponentialRampToValueAtTime(.001,at+.16);osc.connect(gain).connect(audioContext.destination);osc.start(at);osc.stop(at+.18);}}catch{}}
function setHTML(el,html){if(el.dataset.html!==html){el.innerHTML=html;el.dataset.html=html;return true}return false;}
function render(){
 if(!$('#world'))$('#app').innerHTML=`<main id="game"><section id="world"><canvas id="backdrop"></canvas><div class="vignette"></div><header id="world-head"></header><div id="actors"></div><div id="fx-layer" aria-hidden="true"></div><div id="scene-caption"></div><div id="battle-feed" aria-live="polite"></div><div id="party-hud"></div><aside id="enemy-hud" aria-label="Party dos inimigos"></aside><div id="expedition-vote" aria-live="polite"></div><nav id="commands" aria-label="Comandos"></nav></section><div id="window-backdrop" hidden></div><section id="game-window" role="dialog" aria-modal="true" aria-labelledby="window-title" hidden><header><h2 id="window-title"></h2>${btn('×','close','','', 'close-window')}</header><div id="window-content"></div></section></main>`;
 const s=room?.state,p=player();$('#game').classList.toggle('in-combat',s?.phase==='combat');
 setHTML($('#world-head'),`<div><small>${esc(s?.biome||'Santuário dos ecos')}</small><span>${s?'Profundidade '+s.stage+' · '+(s.phase==='combat'?'ATB / espera':'descanso'):'ABISMO DOS ECOS'}</span></div><div class="head-controls">${s?btn('Mapa','map','aria-label="Abrir mapa da jornada"'):''}${btn(soundOn?'♫':'♪','sound','aria-label="Ativar ou silenciar sons"')}${btn('☰','menu','aria-label="Abrir menu do jogo"')}</div>`);
 if($('#backdrop').dataset.stage!==String(s?.stage||0)){battleScene($('#backdrop'),s?.stage||1);$('#backdrop').dataset.stage=String(s?.stage||0);}
 const arena=arenaHold||s,live=arena?.enemies.filter(e=>e.hp>0)||[];if(!live.some(e=>e.id===target))target=live[0]?.id;
 const heroes=arena?.players||[{id:'preview',classId:selectedClass,raceId:selectedRace,name:draftName,equipment:{},hp:1}];
 const skins=new Map();const slot=(key,skin,draw)=>{skins.set(key,draw);return `<span class="sprite-slot" data-sprite-slot="${esc(key)}" data-skin="${esc(skin)}"></span>`};
 const heroSkin=q=>[q.classId,q.raceId,q.ultra,q.equipment?.weapon?.name,q.equipment?.weapon?.rarity].join('|');
 let html=`<div class="heroes ${heroes.length>4?'crowded':''}" data-group="heroes">${heroes.map((q,i)=>`<button data-unit="hero:${esc(q.id)}" class="hero-unit ${q.hp<=0?'fallen':''} ${q.id===profile.id?'mine':''} ${pending?'selectable':''}" data-do="ally" data-id="${esc(q.id)}" data-actor="${esc(q.id)}" style="--slot:${i}" aria-label="${esc(q.name)}${q.hp<=0?' caído':''}"><small>${esc(q.name)}</small>${slot('hero:'+q.id,heroSkin(q),()=>heroSprite(q))}${q.summons?.length?`<span class="summon-band">${q.summons.map(pet=>`<span data-unit="pet:${pet.id}" class="pet" data-pet="${pet.id}" tabindex="0">${slot('pet:'+pet.id,pet.kind,()=>summonSprite(pet))}${meter(pet.hp,pet.maxHp)}<small>${esc(pet.name)}</small></span>`).join('')}</span>`:''}</button>`).join('')}</div>`;
 if(arena?.phase==='combat')html+=`<div class="monsters" data-group="monsters">${arena.enemies.map((e,i)=>{const atb=atbInfo(arena,e,true);return `<button data-unit="enemy:${e.id}" class="monster ${e.hp<=0?'fallen':''} ${target===e.id?'target':''} ${e.boss?'boss':''} ${enemyIntent(arena,e).ultimate?'ultimate-ready':''}" style="--slot:${i}" data-do="target" data-id="${e.id}" data-enemy="${e.id}" ${e.hp<=0?'disabled':''}><span class="intent">${esc(enemyIntent(arena,e).label)}</span>${slot('enemy:'+e.id,[e.species,e.art,e.type,e.boss].join('|'),()=>monsterSprite(e))}<strong>${esc(e.name)}</strong>${meter(e.hp,e.maxHp)}${meter(atb.percent,100,'atb')}<small>${e.hp}/${e.maxHp} · ATB ${Math.round(atb.percent)}%</small></button>`}).join('')}</div>`;
 patchArena($('#actors'),html,key=>skins.get(key)?.());
 effects??=new BattleEffects($('#world'));
 tooltips??=attachUnitTooltips({getState:()=>room?.state,getStats:stats,heroDelay:actionDelay});tooltips.refresh();
 setHTML($('#scene-caption'),s?.phase==='combat'?'':`<div><small>${s?.phase==='defeat'?'SEU ECO PERMANECE':s?.phase==='victory'?'VOCÊ VOLTOU':'O CAMINHO NÃO TEM FIM'}</small><h1>${s?.phase==='defeat'?'O abismo venceu.':s?.phase==='victory'?'Até a próxima descida.':s?.phase==='camp'?esc(s.shop?.name||'Uma fogueira acesa'):s?.phase==='reward'?'Um breve silêncio.':'&lt;Inserir nome de jogo de RPG&gt;'}</h1>${btn(!s?'Criar personagem':s.phase==='lobby'?'Preparar expedição':s.phase==='camp'?'Visitar mercador':s.phase==='reward'?'Recolher e avançar':s.phase==='route'?'Escolher caminho':s.phase==='event'?'Investigar':'Voltar ao santuário',!s?'create':s.phase==='lobby'?'lobby':['defeat','victory'].includes(s.phase)?'leave':'journey')}</div>`);
 setHTML($('#party-hud'),s?`<div class="party-strip">${s.players.map(q=>{const v=stats(q);return `<button data-do="ally" data-id="${esc(q.id)}" class="party-chip ${s.phase==='combat'&&q.acted?'charging':'ready'} ${q.id===p?.id?'controlled':''} ${q.hp<=0?'down':''}"><b>${esc(q.name)}${q.ultra?' · '+esc(q.ultra):''}</b><span>PV ${q.hp}/${v.hp}</span>${meter(q.hp,v.hp)}<span>PM ${q.mana}/${v.mana}</span>${meter(q.mana,v.mana,'mp')}${s.phase==='combat'?meter(q.acted?Math.max(0,100-((q.nextAt||0)-(s.clock||0))/actionDelay(q)*100):100,100,'atb'):''}<small>${q.hp<=0?'Caído':s.phase==='combat'?(q.acted?'Recarregando':'Pronto'):'Nível '+q.level}</small></button>`}).join('')}</div>`:'');
 setHTML($('#enemy-hud'),s?.phase==='combat'?`<small class="enemy-heading">INIMIGOS · ${s.enemies.filter(e=>e.hp>0).length}</small><div class="enemy-strip">${s.enemies.map(e=>{const atb=atbInfo(s,e,true),intent=enemyIntent(s,e);return `<button data-do="target" data-id="${esc(e.id)}" data-enemy="${esc(e.id)}" class="enemy-chip ${target===e.id?'target':''} ${e.hp<=0?'down':''} ${intent.ultimate?'ultimate-ready':''}" ${e.hp<=0?'disabled':''}><b>${esc(e.name)}</b><span>PV ${e.hp}/${e.maxHp}</span>${meter(e.hp,e.maxHp)}<span>ATB ${Math.round(atb.percent)}% · ${atb.remaining} UT</span>${meter(atb.percent,100,'atb')}<small>${esc(e.hp<=0?'Caído':intent.label)}</small></button>`}).join('')}</div>`:'');
 director??=new SceneDirector({world:$('#world'),getAudio:()=>audioContext,drawEvent:eventSprite,drawHero:heroSprite,initialStory:personalStory(s,p?.id)?.id});director.update(s,p,soundOn);
 const can=p&&p.hp>0&&!p.acted&&!busy;
 setHTML($('#commands'),s?.phase==='combat'?`${btn('1 · Atacar','attack','',!can)}${btn('2 · Skills','skills','',!can)}${btn('3 · Magia','magic','',!can)}${btn('4 · Defender','defend','',!can)}${btn('Poção · '+p.potions,'potion','',!can||!p.potions)}${btn('Mochila','inventory')}${btn('Registro','log')}`:`${s?btn('Personagem','build')+btn('Mochila','inventory')+btn('Party','party'):''}${btn('Legado','legacy')}${btn('Conta','account')}`);
 const commands=$('#commands');let note=$('#turn-note');if(!note){note=document.createElement('small');note.id='turn-note';commands.after(note);}note.textContent=s?.phase==='combat'?(busy?'Confirmando ação…':p?.acted?'Aguardando: '+s.players.filter(q=>q.hp>0&&!q.acted).map(q=>q.name).join(', '):''):'';
 setHTML($('#battle-feed'),s&&logOpen?`<div class="battle-log">${s.log.slice(-10).map(x=>`<p class="${x.kind}">${esc(x.text)}</p>`).join('')}</div>`:s?.phase==='combat'?`<div class="latest-log">${esc(s.log.at(-1)?.text||'')}</div>`:'');
 const vote=decisionStatus(s);setHTML($('#expedition-vote'),vote?`<button data-do="vote"><b>${esc(DECISIONS[vote.kind].label)}</b><span>${vote.voted}/${vote.total} votaram · <strong data-vote-clock="${vote.id}">10s</strong> · Abrir votação</span></button>`:'');
 const latestArea=s?.journey?.areas.at(-1);if(latestArea&&!arenaHold&&!document.hidden&&(s.stage>latestArea.end||s.phase==='victory')&&reportSeen[room.id]!==latestArea.id){areaReportId=latestArea.id;panel='area';reportSeen[room.id]=latestArea.id;try{localStorage.setItem('abismo-reports-v7',JSON.stringify(Object.fromEntries(Object.entries(reportSeen).slice(-32))))}catch{}sound('level');}
 const signature=p?.talentOffers?.join('|');if((!panel||panel==='journey'||panel==='lobby')&&!arenaHold&&p?.talentPoints&&signature&&signature!==talentSeen&&s.phase!=='combat'){panel='talents';talentSeen=signature;sound('level');}
 renderWindow();updateVoteClock();
}
const titles={vote:'Decisão da party',map:'Mapa da jornada',area:'Uma nova fronteira',accomplishments:'Feitos da expedição',create:'Seu próximo eco',lobby:'Preparação',menu:'Menu',skills:'Técnicas de combate',magic:'Conjuração',ally:'Escolha um aliado',inventory:'Equipamento',build:'Personagem · SPECIAL',tree:'Árvore de evolução',talents:'Escolha um talento',traits:'Traits',party:'Party',legacy:'Árvore de ecos',journey:'O próximo passo',account:'Conta e conexão',guide:'Como sobreviver'};
function renderWindow(){const el=$('#game-window'),back=$('#window-backdrop');el.hidden=!panel;back.hidden=!panel;if(!panel)return;$('#window-title').textContent=titles[panel]||'Abismo';const body=$('#window-content'),scroll=body.scrollTop;const html=({vote:()=>room?voteView(room.state,profile.id):'<p>Entre em uma expedição.</p>',map:()=>room?journeyMap(room.state):'<p>Entre em uma expedição.</p>',area:()=>room?areaReport(room.state,areaReportId):'<p>Entre em uma expedição.</p>',accomplishments:()=>room?accomplishments(room.state):'<p>Entre em uma expedição.</p>',create:createView,lobby:lobbyView,menu:menuView,skills:skillsView,magic:magicView,ally:allyView,inventory:inventoryView,build:buildView,tree:treeView,talents:talentsView,traits:traitsView,party:partyView,legacy:legacyView,journey:journeyView,account:accountView,guide:guideView}[panel]||menuView)();if(setHTML(body,html))body.scrollTop=scroll;el.className='window-'+panel;}
function menuView(){return `<div class="menu-list">${[['map','Mapa da jornada'],['accomplishments','Feitos da expedição'],['journey','Próximo passo'],['inventory','Equipamento'],['build','SPECIAL e traits'],['tree','Evoluções'],['party','Party'],['legacy','Legado de ecos'],['magic','Grimório'],['guide','Guia'],['account','Conta']].map(([k,n])=>btn(n,k)).join('')}</div>`;}
function specialEditor(v,draft=false){return `<div class="special-list">${SPECIAL.map(x=>`<div><b>${x.id}</b><span><strong>${x.name}</strong><small>${x.desc}</small></span>${draft?btn('−','draftStat',`data-stat="${x.id}" data-n="-1"`,v[x.id]<=1):''}<em>${v[x.id]??5}</em>${btn('+',draft?'draftStat':'stat',`data-stat="${x.id}" data-n="1"`,draft?v[x.id]>=10||Object.values(v).reduce((a,b)=>a+b,0)>=40:!player()?.statPoints||room.state.phase==='combat')}</div>`).join('')}</div>`;}
function createView(){return `<label>Nome<input id="name" maxlength="24" value="${esc(draftName)}"></label><div class="character-pick"><div class="preview-hero">${heroSprite({classId:selectedClass,raceId:selectedRace,equipment:{}})}</div><div><label>Classe<select id="class">${CLASSES.map(c=>`<option value="${c.id}" ${c.id===selectedClass?'selected':''}>${c.name}</option>`).join('')}</select></label><p>${CLASSES.find(c=>c.id===selectedClass).role}. A classe define técnicas, não seus atributos.</p><label>Raça<select id="race">${RACES.map(r=>`<option value="${r.id}" ${selectedRace===r.id?'selected':''} ${r.cost&&!meta().races.includes(r.id)?'disabled':''}>${r.name}${r.cost?' · '+r.cost+' ecos':''}</option>`).join('')}</select></label><p>${esc(RACES.find(r=>r.id===selectedRace).desc)}<br>${Object.entries(RACES.find(r=>r.id===selectedRace).special||{}).map(([k,v])=>`${v>0?'+':''}${v} ${k}`).join(' · ')}</p></div></div><h3>SPECIAL · ${40-Object.values(draftSpecial).reduce((a,b)=>a+b,0)} pontos livres</h3>${specialEditor(draftSpecial,true)}<details class="traits-picker" ${traitsExpanded?'open':''}><summary>Traits · ${draftTraits.length}/12 escolhidas · saldo ${-draftTraits.reduce((n,id)=>n+TRAITS.find(t=>t.id===id).cost,0)} pontos</summary><p>Desvantagens financiam vantagens. Você pode começar sem traits.</p>${traitsList(draftTraits,true)}</details>${mode==='online'?`<label>Nome da sala<input id="serverName" value="${esc(draftServer)}"></label>`:''}<div class="sticky-actions">${btn(mode==='online'?'Criar sala':'Começar expedição','createRun','','','primary')}${mode==='online'?btn('Buscar salas','servers'):btn('Jogar online','online')}</div>${mode==='online'?`<div class="servers">${serverList.map(r=>btn(`${esc(r.name)} · ${r.players}/20`,'join',`data-code="${esc(r.code)}"`)).join('')}<label>Código da sala<input id="joinCode" value="${esc(draftJoin)}"></label>${btn('Entrar por código','join')}</div>`:''}`;}
function traitsList(ids,editable){const visible=editable?TRAITS.filter(t=>traitFilter==='all'||traitFilter==='positive'&&t.cost>0||traitFilter==='negative'&&t.cost<0||traitFilter==='selected'&&ids.includes(t.id)):TRAITS.filter(t=>ids.includes(t.id));return `${editable?`<div class="trait-filter">${[['all','Todas'],['positive','Vantagens'],['negative','Desvantagens'],['selected','Escolhidas']].map(([id,name])=>btn(name,'traitFilter',`data-id="${id}"`,false,traitFilter===id?'chosen':'')).join('')}</div>`:''}<div class="traits-grid">${visible.map(t=>btn(`<strong>${t.name}</strong><span>${t.cost<0?'+'+(-t.cost)+' pontos':'Custa '+t.cost}</span><small>${t.desc}</small>`,editable?'draftTrait':'noop',`data-id="${t.id}"`,!editable,ids.includes(t.id)?'chosen':'' )).join('')}</div>${!visible.length?'<p>Nenhuma trait selecionada.</p>':''}`;}

function traitsView(){return traitsList(player()?.traits||[],false);}
function lobbyView(){return `<p>Sala ${esc(room.code)} · ${room.state.players.length}/20</p>${partyView()}<div class="sticky-actions">${btn('Votar para iniciar','start','','','primary')}${btn('Copiar convite','copyRoom')}${btn('Sair','leave')}</div>`;}
function skillDescription(sk){const d=skillDetails(sk);return `<small class="skill-meta">${esc(d.target)} · ${esc(TYPE_LABEL[sk.type]||sk.type)} · ${sk.cost} PM</small><span class="skill-effects">${d.lines.map(line=>`<span>${esc(line)}</span>`).join('')}</span>`;}
function skillsView(){const p=player();if(!p)return '<p>Crie um personagem.</p>';return `<p class="muted">Escolha uma técnica e depois o alvo indicado. Potência é um multiplicador: o dano final depende dos atributos, resistências e bônus. UT são unidades de tempo do ATB.</p><div class="skill-list">${skillsFor(p).map(sk=>btn(`<span><strong>${esc(sk.name)}</strong>${skillDescription(sk)}</span>`,'combatSkill',`data-id="${sk.id}"`,p.mana<sk.cost||p.acted||p.hp<=0||room.state.phase!=='combat')).join('')}</div><p>Novas técnicas nos níveis 2, 4 e 6 e nos nós da superclasse.</p>`;}

function magicView(){const p=player(),sp=resolveSpell(runes.join(' ')),learned=meta().spells.map(resolveSpell).filter(Boolean);return `<div class="rune-sequence">${runes.map((r,i)=>btn(r,'removeRune',`data-i="${i}"`)).join('')}${!runes.length?'<span>Toque nas runas para começar.</span>':''}</div><p>${runes.length}/12 runas · ${sp?esc(sp.name)+' · '+spellCost(p||{raceId:selectedRace,talents:[],traits:[],meta:meta()},sp)+' PM':'Fórmula instável'}</p><div class="rune-keys">${RUNE_DATA.map(r=>btn(`<b>${r.id}</b><small>${r.name}</small>`,'addRune',`data-id="${r.id}"`,runes.length>=12)).join('')}</div><div class="sticky-actions">${btn('Limpar','clearRunes')}${btn('Conjurar','cast','',!p||room.state.phase!=='combat'||p.acted||p.hp<=0||(sp&&p.mana<spellCost(p,sp)), 'primary')}</div><details><summary>Grimório · ${learned.length} descobertas</summary><div class="known-spells">${learned.map(x=>btn(`${esc(x.name)} · ${x.cost} PM`,'prepare',`data-combo="${esc(x.combo)}"`)).join('')}</div></details><details><summary>Fragmento proibido: DEATH TOUCH · 100 PM</summary><code>${DEATH_TOUCH}</code><p>12 runas. Executa inimigos comuns; chefes perdem 35% de sua vida máxima.</p>${btn('Preparar Death Touch','prepare',`data-combo="${DEATH_TOUCH}"`)}</details>`;}
function allyView(){return `<p>${esc(pending?.label||'Selecione quem receberá a ação.')}</p><div class="ally-picker">${room.state.players.map(q=>{const v=stats(q),dead=pending?.revive;return btn(`${heroSprite(q)}<strong>${esc(q.name)}</strong><span>${q.hp}/${v.hp} PV</span>${meter(q.hp,v.hp)}<small>${q.hp<=0?'Caído':q.status.silence?'Silenciado':q.formation==='back'?'Retaguarda':'Frente'}</small>`,'pickAlly',`data-id="${esc(q.id)}"`,dead?q.hp>0:q.hp<=0)}).join('')}</div>`;}
function inventoryView(){const p=player();if(!p)return '<p>Crie um personagem primeiro.</p>';const positions=pack(p.bag)||[],it=p.bag.find(x=>x.id===inspect),can=!['combat','defeat','victory'].includes(room.state.phase);return `<div class="inventory-heading"><span>${p.gold} ouro</span><small>Segure o botão esquerdo e arraste pelos itens para selecionar vários.</small></div><div class="inventory-body"><div class="paperdoll">${heroSprite(p)}<strong>${esc(p.ultra||CLASSES.find(c=>c.id===p.classId).name)}</strong><div class="equipment-slots">${Object.entries(p.equipment).map(([slot,it])=>btn(`${itemIcon(slot,it?.rarity,it?.name)}<span>${esc(it?.name||({weapon:'Arma',armor:'Armadura',helm:'Elmo',ring:'Anel',amulet:'Amuleto'})[slot])}</span>`,'unequip',`data-slot="${slot}"`,!it||!can)).join('')}</div></div><div><div class="bag-grid">${p.bag.map(it=>{const pos=positions.find(x=>x.id===it.id);return `<button data-do="inspect" data-id="${it.id}" data-item="${it.id}" title="${esc(it.name)}" aria-label="${esc(it.name)}" class="bag-item ${selected.has(it.id)?'selected':''}" style="--rarity:${RARITIES[it.rarity].color};grid-column:${pos.x+1}/span ${it.w};grid-row:${pos.y+1}/span ${it.h}">${itemIcon(it.slot,it.rarity,it.name)}<small>${it.rarity===5?'M':''}</small></button>`}).join('')}</div><div class="bulk-actions">${btn(`Vender ${selected.size} selecionados`,'sellMany','',!selected.size||!can)}${btn('Limpar seleção','clearSelected')}</div><div class="item-details">${it?`<small style="color:${RARITIES[it.rarity].color}">${RARITIES[it.rarity].name}</small><h3>${esc(it.name)}</h3><p>${Object.entries(it.mods).map(([k,n])=>`${k}: +${Number(n.toFixed(2))}`).join(' · ')}</p><p>Requisitos: ${Object.entries(it.requirements||{}).map(([k,n])=>`${k} ${n}`).join(' · ')}${it.classId?' · '+CLASSES.find(c=>c.id===it.classId).name:''}</p>${it.lore?'<p>'+esc(it.lore)+'</p>':''}${it.mythic?'<p class="mythic">Relíquia única de classe · efeito '+esc(it.mythic)+'</p>':''}${btn('Equipar','equip',`data-id="${it.id}"`,!can||!equipmentAllowed(p,it),'primary')}${btn('Vender · '+salePrice(p,it),'sell',`data-id="${it.id}"`,!can)}`:'<p>Selecione uma peça para inspecionar.</p>'}</div></div></div>`;}
function buildView(){const p=player();if(!p)return '<p>Crie um personagem.</p>';const v=stats(p);return `<div class="build-title">${heroSprite(p)}<div><h3>${esc(p.name)} · ${esc(p.ultra||EVOLUTIONS[p.classId]?.[p.evolution]?.name||CLASSES.find(c=>c.id===p.classId).name)}</h3><p>Nível ${p.level} · ${p.statPoints} pontos SPECIAL · ${p.points} evolução</p><p>PV ${v.hp} · PM ${v.mana} · armadura ${v.armor} · crítico ${v.crit.toFixed(1)}%</p></div></div>${specialEditor(p.special||Object.fromEntries(SPECIAL.map(x=>[x.id,5])))}<p>Bônus raciais: ${Object.entries(RACES.find(r=>r.id===p.raceId).special||{}).map(([k,v])=>`${k} ${v>0?'+':''}${v}`).join(' · ')||'nenhum'}</p><div class="sticky-actions">${btn('Evoluções','tree')}${btn('Traits','traits')}${btn('Cartas · '+p.talentPoints,'talents','',!p.talentPoints)}</div><details class="learned-talents"><summary>Talentos adquiridos · ${p.talents.length}</summary>${p.talents.map(id=>TALENTS.find(t=>t.id===id)).filter(Boolean).map(t=>`<p><b>${esc(t.name)}</b><br><small>${esc(t.desc)}</small></p>`).join('')}</details>`;}
function treeView(){const p=player();if(!p)return '<p>Crie um personagem.</p>';const trees=EVOLUTIONS[p.classId],b=p.evolution??treeBranch,tree=trees[b],blocked=room.state.phase==='combat';const preview=skillsFor({...p,level:99,evolution:b,ultra:tree.ultra,skills:Object.fromEntries([...tree.nodes,...tree.ultraNodes].map(n=>[n.id,1]))});const nodeSkill=(n,i)=>n.skill||(n.effect.startsWith('active')?preview.find(sk=>sk.id==='evo_'+i):null);const nodeButton=(n,i,ultra=false)=>btn(`<small>NV.${n.level}${n.skill||n.effect.startsWith('active')?' · TÉCNICA':' · PASSIVA'}</small><strong>${esc(n.name)}</strong><span>${esc(n.desc)}</span>${nodeSkill(n,i)?skillDescription(nodeSkill(n,i)):''}<em>${n.req.length?'Requer: '+n.req.map(k=>tree.nodes.concat(tree.ultraNodes).find(x=>x.id===k)?.name||k).map(esc).join(' + '):'Início do caminho'}</em>`,ultra?'ultraEvolve':'evolve',ultra?`data-node="${n.id}"`:`data-branch="${b}" data-node="${i}"`,!!p.skills[n.id]||!p.points||p.level<n.level||!n.req.every(k=>p.skills[k])||blocked||(ultra&&(!p.ultra||(p.ultraLane!=null&&p.ultraLane!==n.lane))),`tree-node ${p.skills[n.id]?'learned':''}`);return `<p>${p.points} pontos · cinco superclasses; três caminhos internos em cada uma. Complete os ${tree.nodes.length} nós da superclasse para ascender no nível 50.</p><div class="branch-tabs">${trees.map((t,i)=>btn(t.name,'branch',`data-i="${i}"`,p.evolution!=null&&p.evolution!==i,b===i?'active':'')).join('')}</div><details class="tree-foundation" ${tree.nodes.slice(0,12).every(n=>p.skills[n.id])?'':'open'}><summary>Fundamentos · ${tree.name}</summary><div class="deep-foundation">${tree.nodes.slice(0,12).map((n,i)=>nodeButton(n,i)).join('')}</div></details><div class="deep-paths">${['Assalto','Controle','Vínculo'].map((title,lane)=>`<section><h3>${title}</h3><div class="path-chain">${tree.nodes.map((n,i)=>({n,i})).filter(({n})=>n.effect==='deep'&&n.lane===lane).map(({n,i})=>nodeButton(n,i)).join('')}</div></section>`).join('')}</div><div class="ultra-node">${btn(`<small>ULTRA · NÍVEL 50</small><strong>${tree.ultra}</strong><span>+50% poder, +25% PV, +20% PM. Abre uma nova árvore de especialização.</span>${skillDescription(preview.find(sk=>sk.id==='ultra'))}`,'ultra','',!!p.ultra||p.level<50||p.points<3||!tree.nodes.every(n=>p.skills[n.id])||blocked)}</div><details class="ultra-tree" ${p.ultra?'open':''}><summary>Árvore ULTRA · ${tree.ultra} · escolha um caminho por expedição</summary><div class="deep-paths">${['Devastação','Dominação','Comunhão'].map((title,lane)=>`<section><h3>${title}${p.ultraLane===lane?' · escolhido':''}</h3><div class="path-chain">${tree.ultraNodes.filter(n=>n.lane===lane).map(n=>nodeButton(n,0,true)).join('')}</div></section>`).join('')}</div></details>`;}

function talentsView(){const p=player();if(!p)return '';const offers=(p.talentOffers||[]).map(id=>TALENTS.find(t=>t.id===id)).filter(Boolean);return `<p>Escolha uma. As outras cartas se perdem. ${p.talentPoints} escolha(s) pendente(s).</p><div class="talent-cards">${offers.map(t=>btn(`<small>${t.rarity} · ${t.tree}</small><h3>${esc(t.name)}</h3><p>${esc(t.desc)}</p><span>Requisitos: ${Object.entries(t.req).map(([k,n])=>k.toUpperCase()+' '+n).join(' / ')}${t.level?' · nível '+t.level:''}${t.ultraOnly?' · classe ultra':''}</span>`,'talent',`data-id="${t.id}"`,!p.talentPoints||room.state.phase==='combat')).join('')}</div>${!offers.length?`<p>Nenhuma carta elegível agora. Guarde suas escolhas e invista em SPECIAL.</p>${btn('Verificar cartas','refreshTalents','',!p.talentPoints)}`:''}`;}
function partyView(){return room?`<p>Frente protege a retaguarda. Marque um alvo e deixe outro aliado consumir a marca: +40% de dano. Combine fogo/gelo e gelo/raio entre jogadores.</p><div class="party-list">${room.state.players.map(q=>`<article>${heroSprite(q)}<div><h3>${esc(q.name)} · ${q.level}</h3><p>${esc(CLASSES.find(c=>c.id===q.classId).name)} · ${q.formation==='back'?'Retaguarda':'Frente'} · ${q.summons.length}/${summonCap(q)} servos</p>${q.id===profile.id?btn('Frente','formation','data-row="front"',room.state.phase==='combat')+btn('Retaguarda','formation','data-row="back"',room.state.phase==='combat'):''}</div></article>`).join('')}</div>`:'<p>Crie ou entre em uma sala. Até 20 jogadores.</p>';}
function legacyView(){const m=meta();return `<p>${m.shards} ecos · ${m.runs} expedições. Cada ramo bifurca e volta a se encontrar na memória final. Bônus entram no próximo personagem.</p><div class="echo-branches">${ECHO_TREE.map(branch=>`<details class="echo-branch" data-echo="${branch.id}" ${echoOpen===branch.id?'open':''}><summary>${branch.name}</summary><div class="echo-graph">${branch.nodes.map(n=>{const lv=m.upgrades[n.id]||0;return btn(`<strong>${n.name}</strong><small>${n.desc}</small><span>${lv}/${n.max} · ${n.base+lv*n.step} ecos</span><em>${n.requires.length?'Após: '+n.requires.map(id=>branch.nodes.find(x=>x.id===id)?.name).join(' + '):'Raiz'}</em>`,'upgrade',`data-id="${n.id}" style="grid-row:${n.row};grid-column:${n.column};--row:${n.row}"`,!!room||lv>=n.max||m.shards<n.base+lv*n.step||!n.requires.every(k=>m.upgrades[k]>0),`echo-node ${lv?'learned':''} ${n.column===2?'merge-node':''}`)}).join('')}</div></details>`).join('')}</div><h3>Linhagens</h3><div class="race-shop">${RACES.filter(r=>r.cost).map(r=>btn(`<strong>${r.name}</strong><small>${r.desc}</small><span>${m.races.includes(r.id)?'Desbloqueado':r.cost+' ecos'}</span>`,'unlockRace',`data-id="${r.id}"`,!!room||m.races.includes(r.id)||m.shards<r.cost)).join('')}</div>`;}

function journeyView(){if(!room)return '<p>Entre em uma expedição.</p>';return `<div class="journey-navigation">${btn('Mapa da jornada','map')}${btn('Feitos','accomplishments')}</div>`+(decisionStatus(room.state)?voteView(room.state,profile.id):journeyBody());}
function journeyBody(){const s=room.state,p=player();if(s.phase==='route')return routePoll(s,profile.id);if(s.phase==='camp')return `<div class="npc-head">${heroSprite({classId:s.shop?.name.includes('Brunna')?'artifice':s.shop?.name.includes('Ivo')?'alquimista':'clerigo'})}<div><h3>${esc(s.shop?.name||'Mercador')}</h3><p>“O estoque está na mesa. Escolha com cuidado.”</p><small>${p.gold} ouro · peças únicas neste estoque, compartilhado pela party.</small></div></div><div class="shop-stock">${(s.shop?.stock||[]).map(it=>btn(`${itemIcon(it.slot,it.rarity,it.name)}<span><strong style="color:${RARITIES[it.rarity].color}">${esc(it.name)}</strong><small>${Object.entries(it.mods).map(([k,v])=>k+' +'+v).join(' · ')}</small></span><b>${shopPrice(p,it)} ouro</b>`,'shopBuy',`data-id="${it.id}"`,p.gold<shopPrice(p,it))).join('')}</div><div class="sticky-actions">${btn('Poção · '+Math.ceil(24*(1-(p.meta.upgrades.bargain||0)*.03))+' ouro','buyPotion')}${btn('Vender equipamento','inventory')}${btn('Tratar lesões · '+(90+s.stage*12)+' ouro','treat','',!Object.values(p.injuries||{}).some(Boolean)||p.gold<90+s.stage*12)}${btn('Votar para avançar','ready','','','primary')}</div>`;if(s.phase==='reward')return `${s.event?.special?adventureResult(s,p):''}<p>Todos os espólios estão na mochila. Distribua os pontos antes de descer.</p><div class="menu-list">${btn('Equipamento','inventory')}${btn('SPECIAL e evolução','build')}${p.talentPoints?btn('Escolher talento','talents'):''}${btn('Votar para avançar','ready','','','primary')}${s.checkpoint?btn('Propor extração','extract'):''}</div>`;if(s.phase==='event'&&s.event.special)return adventureView(s,p);if(s.phase==='event')return `<h3>${esc(s.event.name)}</h3><p>${esc(s.event.text)}</p><p>CD ${s.event.dc} · falhar ignora escudo/armadura: 55% PV + profundidade, lesão persistente, −45% ouro, −40% mana máxima e −1 poção.</p>${btn(s.event.choice,'encounter','',p.encounterDone,'primary')}${btn('Passar com segurança','skipEvent','',p.encounterDone)}`;return '<p>Nenhuma decisão pendente.</p>';}
function accountView(){const recovery=localStorage.getItem('abismo-recovery-'+profile.id);return `<p>${esc(profile.name)} · ${mode==='online'?'Supabase conectado':'Salvamento local'}</p><div class="menu-list">${mode==='local'?btn('Conectar online','online'):btn('Voltar ao solo','local')}${btn('Exportar backup','export')}${mode==='local'?btn('Importar backup','import'):''}${profile.active_room&&!room?btn('Retomar sala','resume'):''}${room?btn(room.state.phase==='lobby'?'Sair da sala':'Encerrar expedição','endPrompt'):''}</div>${mode==='online'?`<details><summary>Código secreto da conta</summary><code>${esc(recovery||'Sem código neste navegador')}</code>${btn('Copiar código','copyRecovery')}</details>`:`<label>Código de recuperação<input id="recoverCode" autocomplete="off"></label>${btn('Recuperar conta','recover')}`}<p class="muted">A URL e chave pública da sua Supabase continuam em config.js.</p>`;}
function guideView(){return `<h3>Decisões e jornada</h3><p>Rotas, início, avanço e extração usam maioria da party, com até 10 segundos e alarme sonoro. Votos ausentes não contam como sim; empate mantém a party no lugar. Encerrar exige todos. Você pode mudar ou retirar o voto enquanto a proposta está aberta. O mapa fica no botão Mapa e registra o percurso, os relatórios de área e os feitos.</p><p>Encontros são individuais: sua cena aparece apenas para você, uma vez. O D20 visual para no resultado do servidor, exibindo bônus e dificuldade; 1 e 20 naturais têm suas próprias regras.</p><h3>Combate</h3><p>Esquiva tem limite de 80%. Lesões persistem até tratamento no mercador. Golpes pesados sem defesa causam lesões e sangramento; poções estancam. ATB Wait: velocidade depende de Agilidade. O tempo espera sua decisão. Skills, magias e consumíveis possuem tempos diferentes. Clique num inimigo para selecionar; cura e escudo abrem um seletor visual de aliado.</p><h3>Build</h3><p>40 pontos SPECIAL iniciais; toda classe pode distribuir livremente. Debuffs pagam traits positivas. Doença terminal perde 10% do PV máximo por ciclo. Cada nível dá 2 SPECIAL, 2 evolução e uma escolha de talento RNG elegível.</p><h3>Evolução</h3><p>Escolha uma das cinco superclasses e complete seus 12 nós. Com nível 18 e mais 3 pontos, evolua para ULTRA. Bárbaro/Berserker → TUNG. Ladino/Espectro → Jiangshi.</p><h3>Infinito</h3><p>Chefes a cada 5 profundidades; lojas fixas a cada 4. Extraia após um chefe ou continue sem limite de andares. Inimigos escalam e combinam marca, cura, proteção, silenciamento, drenagem, reflexo e reanimação. Leia as intenções!</p><h3>Loot</h3><p>Itens têm requisitos SPECIAL e combinações de prefixo/sufixo. Mítico: chance exata de 0,1% por item gerado, independente de sorte. Um por classe, com efeito próprio. Segure o botão esquerdo e arraste pela mochila para selecionar venda em massa.</p><h3>Atalhos</h3><p>1 ataque · 2 skills · 3 magia · 4 defesa · I mochila · P party · Esc fecha janela. Sons podem ser desligados no canto superior.</p>`;}
function receive(r){if(room?.id===r.id&&room.revision>=r.revision)return;const old=room;if(panel==='vote'&&old?.state.vote&&!r.state.vote&&r.state.lastVote?.approved)panel=['route','camp','reward','event'].includes(r.state.phase)?'journey':null;const events=fxCursor.accept(r,profile.id),newVisuals=old?.id===r.id&&(r.state.fxSeq||0)>(old.state.fxSeq||0);if(newVisuals){deltaBefore??=old?.state;queuedFX.push(...events);if(old?.state.phase==='combat'&&r.state.phase!=='combat'){arenaHold=old.state;clearTimeout(holdTimer);holdTimer=setTimeout(()=>{arenaHold=null;scheduleRender()},420);}}if(old?.id!==r.id||r.state.phase==='combat'){if(old?.id!==r.id){arenaHold=null;queuedFX=[];}clearTimeout(holdTimer);arenaHold=null;}room=r;lastReceiveAt=Date.now();for(const q of room.state.players){q.meta=normalizeMeta(q.meta);q.traits??=[];q.talentOffers??=[];}if(mode==='local'){profile.meta=player()?.meta||profile.meta;queueSave();}scheduleRender();}
function flushFX(){if(!effects)return;const recent=queuedFX.splice(0);const latestByActor=new Map();for(const ev of recent)latestByActor.set(ev.actor,ev);for(const ev of [...latestByActor.values()].slice(-24))effects.play(ev);if(deltaBefore&&room){for(const q of room.state.players){const delta=q.hp-(deltaBefore.players.find(p=>p.id===q.id)?.hp??q.hp);if(delta)effects.float($(`[data-actor="${CSS.escape(q.id)}"]`),(delta>0?'+':'')+delta,delta>0?'heal':'hurt');}for(const e of room.state.enemies){const delta=e.hp-(deltaBefore.enemies.find(p=>p.id===e.id)?.hp??e.hp);if(delta)effects.float($(`[data-enemy="${e.id}"]`),String(delta),'hurt');}}deltaBefore=null;}

function updateVoteClock(){const v=decisionStatus(room?.state);if(!v){clearInterval(voteTimer);voteTimer=0;return}if(!voteTimer)voteTimer=setInterval(updateVoteClock,250);const now=Date.now()+(mode==='online'?clockOffset:0),left=Math.max(0,(v.deadlineAt-now)/1000),key=room.id+':'+v.id;document.querySelectorAll('[data-vote-clock="'+v.id+'"]').forEach(el=>el.textContent=Math.ceil(left)+'s');document.querySelectorAll('[data-vote-progress="'+v.id+'"]').forEach(el=>el.style.width=Math.min(100,left*10)+'%');document.querySelectorAll('[data-vote-expired="'+v.id+'"]').forEach(el=>el.hidden=left>0);if(document.hidden)return;if(alarmSeen!==key&&left>0){alarmSeen=key;sound('vote');toast('Votação aberta · '+DECISIONS[v.kind].label+' · até 10 segundos.')}if(left>0&&left<=3&&warnSeen!==key){warnSeen=key;sound('voteEnd')}if(left<=0&&!busy){const index=Math.max(0,room.state.players.findIndex(p=>p.id===profile.id)),attempt=resolutionAttempts.get(key)||{count:0,next:v.deadlineAt+index*180};if(now>=attempt.next&&attempt.count<4){resolutionAttempts.set(key,{count:attempt.count+1,next:now+1200});if(resolutionAttempts.size>32)resolutionAttempts.delete(resolutionAttempts.keys().next().value);action({type:'resolveDecision',voteId:v.id},true);}}}

async function connect(){if(!config.supabaseUrl||!config.supabaseKey)throw Error('Supabase não configurada.');if(!client){const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.57.4');client=createClient(config.supabaseUrl,config.supabaseKey);}let {data:{session}}=await client.auth.getSession();if(!session){const result=await client.auth.signInAnonymously();if(result.error)throw result.error;session=result.data.session;}return session;}
async function api(op,extra={}){const session=await connect();const res=await fetch(`${config.supabaseUrl.replace(/\/$/,'')}/functions/v1/game`,{method:'POST',headers:{'Content-Type':'application/json',apikey:config.supabaseKey,Authorization:`Bearer ${session.access_token}`},body:JSON.stringify({op,...extra})});const data=await res.json();if(Number.isFinite(data.serverNow))clockOffset=data.serverNow-Date.now();if(data.room)receive(data.room);if(!res.ok){if(data.conflict&&!data.room)await api('sync',{revision:room?.revision});throw Error(data.error||'Falha de conexão.');}return data;}
async function subscribe(){if(channel)await client.removeChannel(channel);clearInterval(timer);if(!room)return;const id=room.id;realtimeStatus='CONNECTING';channel=client.channel('room-'+id).on('postgres_changes',{event:'UPDATE',schema:'public',table:'rooms',filter:`id=eq.${id}`},event=>{if(room?.id===id)receive(event.new)}).subscribe(status=>{realtimeStatus=status;});timer=setInterval(async()=>{if(document.hidden||busy||!room)return;if(realtimeStatus==='SUBSCRIBED'&&Date.now()-lastReceiveAt<15000)return;try{await api('sync',{revision:room.revision})}catch{}},3000);}

async function servers(){const data=await api('servers');serverList=data.servers||[];panel='create';render();}
async function enterOnline(recovery=false){const code=$('#recoverCode')?.value;const data=await api(recovery?'recover':'account',recovery?{code}:{name:draftName});mode='online';profile=data.profile;profile.meta=normalizeMeta(profile.meta);room=null;if(data.recoveryCode)localStorage.setItem('abismo-recovery-'+profile.id,data.recoveryCode);if(profile.active_room){await api('sync');await subscribe();panel=null;}else{panel='create';await servers();}render();}
async function createRun(code){if(room)throw Error('Saia da sala atual primeiro.');if(draftTraits.reduce((n,id)=>n+(TRAITS.find(t=>t.id===id)?.cost||0),0)>0)throw Error('Os debuffs precisam pagar o custo dos buffs.');if(draftTraits.length>12)throw Error('Escolha até 12 traits.');if(mode==='local'){receive({id:crypto.randomUUID(),code:'SOLO',revision:0,state:createRoom(profile.id,draftName,selectedClass,profile.meta,crypto.getRandomValues(new Uint32Array(1))[0],selectedRace)});profile.name=draftName;}else{await api('rename',{name:draftName});if(code)await api('join',{code,classId:selectedClass,raceId:selectedRace});else await api('create',{classId:selectedClass,raceId:selectedRace,serverName:draftServer,isPublic:true});profile.active_room=room.id;await subscribe();}await action({type:'configure',special:draftSpecial,traits:draftTraits});panel='lobby';render();}
async function action(a,quiet=false){if(busy)return;busy=true;const combat=['attack','special','combatSkill','spell','defend','potion'].includes(a.type);const clientActionId=crypto.randomUUID();a={...a,clientActionId};try{
 if(!['attack','special','combatSkill','spell','defend','potion'].includes(a.type)){clearTimeout(holdTimer);arenaHold=null;}
 if(combat){panel=null;render();const sk=a.type==='combatSkill'?skillsFor(player()).find(x=>x.id===a.skill):a.type==='spell'?resolveSpell(a.combo):null;fxCursor.markOwn(clientActionId);effects.play({actor:profile.id,action:a.type,kind:sk?.kind||a.type,fx:sk?.fx||a.skill||a.combo,type:sk?.type||player().equipment.weapon?.damageType||CLASSES.find(c=>c.id===player().classId).type,target:a.target,ally:a.ally});sound(a.type==='spell'?'spell':a.type==='potion'?'heal':'attack');}
 if(mode==='local')receive({...room,revision:room.revision+1,state:applyAction(room.state,profile.id,a)});else await api('action',{revision:room.revision,action:a});
 selected=new Set([...selected].filter(id=>player()?.bag.some(x=>x.id===id)));
 if(['start','route','ready','encounter'].includes(a.type)&&panel!=='talents')panel=a.type==='encounter'&&room.state.event?.special&&room.state.phase!=='defeat'?'journey':null;
 if(['start','route','ready','extract','abandon','proposeDecision','vote','withdrawVote','cancelDecision','resolveDecision'].includes(a.type)){if(decisionStatus(room.state))panel=quiet?panel:'vote';else if(panel==='vote'||['start','route','ready'].includes(a.type))panel=room.state.lastVote?.rejected?'vote':['route','camp','reward','event'].includes(room.state.phase)?'journey':null;}
 if(a.type==='talent'&&!player()?.talentPoints)panel=null;
 }catch(e){if(!quiet)toast(e.message);else if(mode==='online')try{await api('sync',{revision:room?.revision})}catch{}}finally{busy=false;scheduleRender();}}

async function leave(){if(mode==='online'){await api('leave');profile=(await api('account')).profile;profile.meta=normalizeMeta(profile.meta);if(channel)await client.removeChannel(channel);clearInterval(timer);}else if(player())profile.meta=structuredClone(player().meta);room=null;save();panel='create';selected.clear();render();}
function chooseAlly(payload,label,revive=false){pending={payload,label,revive};panel='ally';render();}
function openPanel(name){panel=name;if(name==='tree')treeBranch=player()?.evolution??0;render();$('#window-content').scrollTop=0;$('#game-window button:not(:disabled)')?.focus({preventScroll:true});}
let dragging=false,dragMoved=false;
document.addEventListener('pointerdown',e=>{const item=e.target.closest('[data-item]');if(e.button===0&&item){dragging=true;dragMoved=false;selected.add(item.dataset.item);item.classList.add('selected');}});
document.addEventListener('pointerover',e=>{const item=e.target.closest('[data-item]');if(dragging&&e.buttons===1&&item){selected.add(item.dataset.item);item.classList.add('selected');dragMoved=true;}});
document.addEventListener('pointerup',()=>{if(dragging){dragging=false;if(dragMoved)renderWindow();}});
document.addEventListener('input',e=>{if(e.target.id==='name')draftName=e.target.value.trim().slice(0,24)||'Viajante';if(e.target.id==='serverName')draftServer=e.target.value;if(e.target.id==='joinCode')draftJoin=e.target.value;});
document.addEventListener('toggle',e=>{if(!e.target.isConnected)return;if(e.target.matches?.('.traits-picker'))traitsExpanded=e.target.open;if(e.target.matches?.('.echo-branch')&&e.target.open)echoOpen=e.target.dataset.echo;},true);
document.addEventListener('change',e=>{if(e.target.id==='class'){selectedClass=e.target.value;render();}if(e.target.id==='race'){selectedRace=e.target.value;render();}});
document.addEventListener('click',async e=>{
 if(e.target.id==='window-backdrop'){panel=null;pending=null;render();return;}const button=e.target.closest('[data-do]');if(!button||button.disabled||busy)return;const d=button.dataset,op=d.do;if(op==='noop')return;sound();try{
 if(Object.hasOwn(titles,op)&&op!=='ally'){openPanel(op);return;}
 if(op==='close'){panel=null;pending=null;render();}
 else if(op==='sound'){soundOn=!soundOn;localStorage.setItem('abismo-sound',JSON.stringify(soundOn));render();}
 else if(op==='target'){target=d.id;render();}
 else if(op==='log'){logOpen=!logOpen;render();}
 else if(op==='ally'){if(pending){await action({...pending.payload,ally:d.id});pending=null;}else openPanel('party');}
 else if(op==='pickAlly'){const payload=pending.payload;pending=null;await action({...payload,ally:d.id});}
 else if(op==='draftStat'){draftSpecial[d.stat]+=Number(d.n);renderWindow();}
 else if(op==='traitFilter'){traitFilter=d.id;traitsExpanded=true;renderWindow();}
 else if(op==='draftTrait'){traitsExpanded=true;draftTraits=draftTraits.includes(d.id)?draftTraits.filter(x=>x!==d.id):[...draftTraits,d.id];renderWindow();}
 else if(op==='createRun'){await createRun();}
 else if(op==='join'){await createRun(d.code||draftJoin.trim());}
 else if(op==='servers'){await servers();}
 else if(op==='online'||op==='recover'){busy=true;try{await enterOnline(op==='recover')}finally{busy=false;render();}}
 else if(op==='local'){if(channel)await client.removeChannel(channel);clearInterval(timer);mode='local';profile=local;room=local.room;panel=room?null:'create';render();}
 else if(op==='resume'){await api('sync');await subscribe();panel=null;render();}
 else if(op==='copyRoom'){await navigator.clipboard.writeText(room.code);toast('Convite copiado.');}
 else if(op==='copyRecovery'){await navigator.clipboard.writeText(localStorage.getItem('abismo-recovery-'+profile.id)||'');toast('Código copiado.');}
 else if(op==='addRune'){if(runes.length<12)runes.push(d.id);renderWindow();}
 else if(op==='removeRune'){runes.splice(Number(d.i),1);renderWindow();}
 else if(op==='clearRunes'){runes=[];renderWindow();}
 else if(op==='prepare'){runes=d.combo.split(' ');renderWindow();}
 else if(op==='cast'){const sp=resolveSpell(runes.join(' ')),payload={type:'spell',combo:runes.join(' '),target};if(['heal','shield','revive'].includes(sp?.kind))chooseAlly(payload,sp.name,sp.kind==='revive');else await action(payload);}
 else if(op==='combatSkill'){const sk=skillsFor(player()).find(x=>x.id===d.id),payload={type:op,skill:d.id,target};if(sk.target==='ally')chooseAlly(payload,sk.name,sk.kind==='revive');else await action(payload);}
 else if(op==='inspect'){inspect=d.id;if(dragMoved){dragMoved=false;return;}renderWindow();}
 else if(op==='clearSelected'){selected.clear();renderWindow();}
 else if(op==='sellMany'){await action({type:op,items:[...selected]});selected.clear();inspect=null;render();}
 else if(['equip','sell','shopBuy'].includes(op)){await action({type:op,item:d.id});inspect=null;render();}
 else if(op==='unequip')await action({type:op,slot:d.slot});
 else if(op==='formation')await action({type:op,row:d.row});
 else if(op==='stat')await action({type:op,stat:d.stat});
 else if(op==='branch'){treeBranch=Number(d.i);renderWindow();}
 else if(op==='ultraEvolve')await action({type:'ultraSkill',node:d.node});
 else if(op==='evolve')await action({type:'skill',branch:Number(d.branch),node:Number(d.node)});
 else if(op==='talent')await action({type:op,talent:d.id});
 else if(op==='route')await action({type:op,index:Number(d.i),...(d.voteId?{voteId:Number(d.voteId)}:{})});
 else if(op==='castVote')await action({type:'vote',voteId:Number(d.voteId),choice:d.choice==='yes'});
 else if(op==='withdrawVote'||op==='cancelDecision'||op==='resolveDecision')await action({type:op,voteId:Number(d.voteId)});
 else if(op==='areaReport'){areaReportId=Number(d.areaId);openPanel('area');}
 else if(op==='extract'||op==='abandon')await action({type:'proposeDecision',kind:op});
 else if(op==='treat')await action({type:'treat'});
 else if(op==='inspectEncounter')await action({type:'inspectEncounter'});
 else if(op==='encounter'||op==='skipEvent')await action({type:'encounter',choice:d.choice,skip:op==='skipEvent'});
 else if(op==='upgrade'||op==='unlockRace'){if(mode==='local'){profile.meta=op==='upgrade'?upgradeMeta(profile.meta,d.id):unlockRace(profile.meta,d.id);save();}else profile=(await api(op,op==='upgrade'?{key:d.id}:{raceId:d.id})).profile;render();}
 else if(op==='leave')await leave();
 else if(op==='endPrompt'){if(['lobby','victory','defeat'].includes(room.state.phase))await leave();else{$('#window-title').textContent='Encerrar expedição?';$('#window-content').innerHTML=`<p>Propor o encerramento abre uma votação de 10 segundos. Todos precisam concordar; a expedição conta como derrota.</p>${btn('Propor encerramento','abandon')}${btn('Continuar','close')}`;}}
 else if(op==='export'){save();const blob=new Blob([JSON.stringify({format:'abismo-v3',profile:mode==='local'?local:{...profile,room}},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='abismo-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 else if(op==='import'){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const f=input.files[0];if(!f||f.size>5000000)throw Error('Arquivo inválido.');const data=JSON.parse(await f.text());if(!['abismo-v2','abismo-v3'].includes(data.format)||!data.profile?.id)throw Error('Backup inválido.');const candidate=data.profile;if(!/^[a-zA-Z0-9-]+$/.test(candidate.id))throw Error('ID inválido.');if(candidate.room){if(candidate.room.state.version!==2||!Array.isArray(candidate.room.state.players))throw Error('Run incompatível.');for(const p of candidate.room.state.players){if(!CLASSES.some(c=>c.id===p.classId)||!RACES.some(r=>r.id===p.raceId)||!Array.isArray(p.talents)||!pack(p.bag))throw Error('Personagem inválido.');stats(p);}}local=candidate;local.meta=normalizeMeta(local.meta);profile=local;room=local.room;save();panel=null;render();toast('Backup restaurado.');}catch(err){toast(err.message)}};input.click();}
 else if(['start','ready','attack','defend','potion','buyPotion','ultra','extract','refreshTalents','abandon','skipAbsent'].includes(op))await action({type:op,target});
 }catch(err){busy=false;toast(err.message||'Ação não concluída.');render();}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){panel=null;pending=null;render();return;}if(panel&&e.key==='Tab'){const els=[...$('#game-window').querySelectorAll('button:not(:disabled),input,select,summary')].filter(x=>x.getClientRects().length),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}return;}if(e.repeat||e.ctrlKey||e.metaKey||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;const op=({i:'inventory',p:'party','1':'attack','2':'skills','3':'magic','4':'defend'})[e.key.toLowerCase()];if(op&&!panel){e.preventDefault();$(`[data-do="${op}"]`)?.click();}});
render();
if(config.autoOnline&&new URLSearchParams(location.search).get('solo')!=='1')enterOnline().catch(e=>{mode='local';profile=local;room=local.room;toast('Online indisponível: '+e.message);render();});


function adventureResult(s,p){const out=s.event?.outcomes?.[p.id];if(!out)return '';return `<section class="adventure-outcome ${out.success?'success':'failure'}"><strong>${out.success?'O encontro deixou sua marca.':'Nem toda lenda termina bem.'}</strong><p>${esc(out.text)}</p>${out.dice?`<small>D20 ${out.dice} + ${out.bonus} / CD ${out.dc}</small>`:''}</section>`;}
function adventureView(s,p){const e=s.event;return `<div class="adventure-head">${eventSprite(e.art)}<div><small>ENCONTRO RARO</small><h3>${esc(e.name)}</h3><p>${esc(e.text)}</p><p class="risk-warning">Falha: até 90% PV + profundidade, lesões, −60% ouro, −50% mana máxima e −1 poção. Pode matar.</p></div></div>${adventureResult(s,p)}${e.clues?.[p.id]?`<p class="adventure-clue">${esc(e.clue)}</p>`:btn('Investigar o local · melhora seus testes','inspectEncounter','',p.encounterDone)}<div class="adventure-options">${e.options.map(o=>{const claimed=QUEST_RELICS[o.reward]&&s.questClaims?.[o.reward];return btn(`<strong>${esc(o.label)}</strong><small>${esc(o.desc)}</small><span>${o.stat} · CD ${o.dc+Math.floor(s.stage/12)-(e.clues?.[p.id]?4:0)}${o.cost?' · '+o.cost+' ouro':''}</span>${claimed?'<em>Esta relíquia já tem um portador.</em>':''}`,'encounter',`data-choice="${o.id}"`,p.encounterDone||!!claimed||p.gold<(o.cost||0));}).join('')}</div>${btn('Recuar sem arriscar','skipEvent','',p.encounterDone)}${p.encounterDone?'<p>Aguardando os outros viajantes.</p>':''}`;}

document.addEventListener('visibilitychange',()=>{document.documentElement.dataset.paused=document.hidden?'1':'0';if(document.hidden){clearTimeout(saveTimer);save();}});

document.documentElement.dataset.paused=document.hidden?'1':'0';
